def bpe_tokenize(text, merges, vocab):
    words = [list(w + "</w>") for w in text.split()]
    for merge in merges:
        a, b = merge
        new_words = []
        for word in words:
            new_word = []
            i = 0
            while i < len(word):
                if i < len(word) - 1 and word[i] == a and word[i+1] == b:
                    new_word.append(a + b)
                    i += 2
                else:
                    new_word.append(word[i])
                    i += 1
            new_words.append(new_word)
        words = new_words
    return [" ".join(w) for w in words]
